SELECT s1.`c0` AS `id`, s1.`c1` AS `doubled`, s1.`c2` AS `__weight` FROM (SELECT s2.`c4` AS `c0`, s2.`c5` AS `c1`, s2.`c3` AS `c2` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c0` AS `c4`, (CAST(s3.`c2` AS BIGINT) * CAST(2 AS BIGINT)) AS `c5` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2`, `__weight` AS `c3` FROM `orders$delta`) AS s4 WHERE ((CAST(10 AS BIGINT) < s4.`c2`) IS TRUE)) AS s3) AS s2) AS s1
